DO $$ DECLARE t text; sensitive boolean; BEGIN FOREACH t IN ARRAY ARRAY['workforce_snapshots','eea12_analyses','barrier_responses','barrier_survey_links','client_share_links','ee_plans','dg_reviews','dg_outcome_analyses','evidence_extractions','plan_gap_analyses','portal_documents','recruitment_vacancies','recruitment_candidates','doel_submissions','reminder_settings','workforce_foundation_periods'] LOOP sensitive:=t IN ('workforce_foundation_periods','recruitment_candidates','portal_documents','evidence_extractions'); EXECUTE format('CREATE POLICY "Delegated entitlement boundary" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (user_id=auth.uid() OR public.can_manage_client(user_id,%L)) WITH CHECK (user_id=auth.uid() OR public.can_manage_client(user_id,%L))',t,sensitive,sensitive); END LOOP; END $$;
COMMENT ON FUNCTION public.can_manage_client(uuid,boolean) IS 'Delegated entitlement is checked independently of request headers; accepted handovers require owner-authorised staff support.';